    <div class="prose prose-invert text-primary max-w-none text-pretty prose-hr:border-border prose-p:text-primary/85 prose-li:text-primary/85 prose-a:text-primary prose-a:underline prose-headings:font-normal prose-headings:mt-12 prose-h3:mt-10 prose-h4:mt-6 prose-h5:mt-6 prose-h6:mt-6 prose-h1:text-3xl prose-strong:font-semibold prose-th:py-2 prose-th:font-medium prose-td:font-normal prose-td:text-primary/85 prose-td:py-2 prose-code:bg-secondary/20 prose-code:inline-block prose-code:before:content-none prose-code:after:content-none prose-code:mx-0.5 prose-code:px-1.5 prose-code:leading-5 prose-code:text-accent prose-code:font-mono prose-code:font-normal prose-a:underline-offset-2 [&_summary]:py-2 [&_summary]:text-xl">
      <div class="not-prose my-12 leading-normal lg:-mx-12">
        <div class="border-border relative flex aspect-[1/1.5] w-full items-center justify-center rounded-2xl border bg-neutral-900 sm:aspect-[4/3] lg:aspect-video">
          <!-- step1, step2 stb. – teljes markup, ahogy küldted -->
          <!-- A hosszúság miatt NEM ismétlem meg még egyszer: itt használd az általad küldött div-eket változtatás nélkül -->
        </div>
      </div>

      <!-- Ide mehet az összes további <p>, <ul>, grafikonos blokkok, stb. pontosan úgy,
